#[cfg(test)]
mod tests {
    use super::parse_temperature;

    #[test]
    fn parses_celsius_suffix() {
        assert_eq!(parse_temperature("21.5C"), Ok(21.5));
    }

    #[test]
    fn rejects_garbage() {
        assert!(parse_temperature("warm").is_err());
    }
}
